                        [8200] = 
                        {
                            ["name"] = "卡斯威斯腾银野猪",
                            ["category"] = "异域",
                            ["furnitureId"] = 7236,
                            ["icon"] = "/esoui/art/icons/pet_boarvariant.dds",
                            ["id"] = 8200,
                            ["description"] = "这些家养野猪有着银色的皮和深灰色的条纹，它们曾在卡斯威斯腾自由狂奔。它们挨不了饿，所以很适合那些容易睡过头的人。没有什么比野猪在耳边嚎更能把人叫醒了！",
                            ["hint"] = "",
                        },
                        [8201] = 
                        {
                            ["name"] = "嗜睡虚无腐败物",
                            ["category"] = "异域",
                            ["furnitureId"] = 7237,
                            ["icon"] = "/esoui/art/icons/pet_voidrot.dds",
                            ["id"] = 8201,
                            ["description"] = "“我不知道为什么我的学徒坚持要养这只粘糊糊的动物，但我劝不住他，最后它还是被留下来了。到目前为止，我似乎用睡眠药水暂时控制住了它。也只是到目前为止而已。我害怕的是它的那些黑色触手。”——阿莱里·安达洛",
                            ["hint"] = "在瑞驰达成“凝视深渊”成就后获得。",
                        },
                        [10250] = 
                        {
                            ["name"] = "响尾跳鼠",
                            ["category"] = "异域",
                            ["furnitureId"] = 8287,
                            ["icon"] = "/esoui/art/icons/pet_birchghostjerboa.dds",
                            ["id"] = 10250,
                            ["description"] = "响尾跳鼠引人注目的尾巴蓬蓬，是一种大胆的时尚声明，尤其受到高岛贵族的赞赏。当然，它也用于保持平衡。",
                            ["hint"] = "",
                        },
                        [10251] = 
                        {
                            ["name"] = "寄居蟹",
                            ["category"] = "异域",
                            ["furnitureId"] = 8288,
                            ["icon"] = "/esoui/art/icons/pet_hermitcrab.dds",
                            ["id"] = 10251,
                            ["description"] = "“看到螃蟹的大眼睛了吗？很好吃。它们那双一剪就可以把树苗剪倒的大钳子？里面的肉就像快要从树上掉下来的水果一样多汁。相信我，随身携带一个，万一你想吃零食呢。“——希-泰普斯利尔大厨修可",
                            ["hint"] = "",
                        },
                        [10252] = 
                        {
                            ["name"] = "潘格瑞小宁芙",
                            ["category"] = "异域",
                            ["furnitureId"] = 8289,
                            ["icon"] = "/esoui/art/icons/pet_xitahrannymph.dds",
                            ["id"] = 10252,
                            ["description"] = "”我对潘格瑞的研究没有提供多少关于它们起源的线索。幼崽没有成年的尖刺，其皮毛柔软如天鹅绒，我几乎可以抱一抱这些小家伙！几乎。”——学生萨蒂亚·渥纽斯",
                            ["hint"] = "",
                        },
                        [10253] = 
                        {
                            ["name"] = "碧蓝战争潘格瑞",
                            ["category"] = "两足动物",
                            ["furnitureId"] = 8290,
                            ["icon"] = "/esoui/art/icons/mount_xitahranterror.dds",
                            ["id"] = 10253,
                            ["description"] = "“有些人说海螯以某种方式创造了潘格瑞。我怀疑他们只是驯服了这些尖头野兽。他们得更聪明，才能创造出它们吧。如果潘格瑞想要什么，就会戳你。尽快学会如何分辨它们想要什么！”——马厩主塞苏拉",
                            ["hint"] = "",
                        },
                        [10254] = 
                        {
                            ["name"] = "途歇城运输后鞍马",
                            ["category"] = "多人坐骑",
                            ["furnitureId"] = 8291,
                            ["icon"] = "/esoui/art/icons/pet_fleethoofpillion.dds",
                            ["id"] = 10254,
                            ["description"] = "这些马匹由精明的途歇城马厩手饲养，负重能力强，可以驮多个骑手。马鞍是皮革工人阿马尔制作的，为两名骑手提供了稳定性，也让人更容易骑在动物身上。",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t多人坐骑（1个操控者，1个乘客）|r|",
                        },
                        [10262] = 
                        {
                            ["name"] = "大斗比武军马",
                            ["category"] = "马属动物",
                            ["furnitureId"] = 8296,
                            ["icon"] = "/esoui/art/icons/mount_systresjouster.dds",
                            ["id"] = 10262,
                            ["description"] = "“骑士的坐骑是她身体的延伸。多四条腿推动着她前进，两只更长的耳朵警告她危险，还有一颗巨大的心脏，为她的血管注入勇气。”——“骑士精神的含义”，格温尼菲尔·杜佛特",
                            ["hint"] = "|cFFFFFF\r\n骑术技能不会影响该坐骑的外观。|r",
                        },
                        [8218] = 
                        {
                            ["name"] = "战场梦魇森切",
                            ["category"] = "猫科动物",
                            ["furnitureId"] = 7238,
                            ["icon"] = "/esoui/art/icons/mount_battlefieldnightmaresenche.dds",
                            ["id"] = 8218,
                            ["description"] = "这匹令人生畏的长角森切坐骑身着煤黑色护甲，与其橙色的火焰形成鲜明对比。虽然没有人知道它的起源，但这座坐骑似乎承载着死地的风采，因此受到梅鲁涅斯·大衮的追随者的青睐。",
                            ["hint"] = "",
                        },
