                        [6458] = 
                        {
                            ["name"] = "无畏者背包小鬼",
                            ["category"] = "魔族",
                            ["furnitureId"] = 6005,
                            ["icon"] = "/esoui/art/icons/pet_undauntedporterscamp.dds",
                            ["id"] = 6458,
                            ["description"] = "“啊，是的，无畏者。他们决定训练小鬼背上背包，可以说是一项了不起的事业。我很想看看有多少装备会丢失。”——法士艾尔达",
                            ["hint"] = "通过达成“月墓古庙征服者”成就获得。",
                        },
                        [8507] = 
                        {
                            ["name"] = "卡斯之矛家兔",
