                        [10619] = 
                        {
                            ["name"] = "隐居处的侍者",
                            ["category"] = "马属动物",
                            ["furnitureId"] = 8559,
                            ["icon"] = "/esoui/art/icons/mount_fieraughservitor.dds",
                            ["id"] = 10619,
                            ["description"] = "“有人做的。我深入了异典，一个纯净思想和潜力的聚集地。而当我撤出时，这个狰狞不眨眼的怪物从阴影里走了出来。它不会离开。它不会游离。为什么？为什么？”——伊拉蒂斯·塞皮乌斯最后的笔记",
                            ["hint"] = "",
                        },
                        [10620] = 
                        {
                            ["name"] = "泰尔阿鲁因小瓜尔",
                            ["category"] = "异域",
                            ["furnitureId"] = 8560,
                            ["icon"] = "/esoui/art/icons/pet_telaruhnguar.dds",
                            ["id"] = 10620,
                            ["description"] = "根据记录显示，泰尔阿鲁因的商人将茶色微光瓜尔与色斑瓜尔进行了杂交。但学者们对此提出异议，认为是帝国军团在管理该地区时偶然创造了它们。不管怎样，它们都是些狡猾的小懒虫。",
                            ["hint"] = "",
                        },
                        [10621] = 
                        {
                            ["name"] = "乌马里尔的辐光麋鹿",
                            ["category"] = "鹿科动物",
                            ["furnitureId"] = 8561,
                            ["icon"] = "/esoui/art/icons/mount_umarilscovenantelk.dds",
                            ["id"] = 10621,
                            ["description"] = "“无羽者试图战胜桑纳特仑人。‘他们的旗帜上描绘着线条粗劣的麋鹿。让我们骑着这种野兽打败他们，让他们颤栗不已。’一个季节结束了，我还没完成自己的工作。愿他们永远保持对他的忠诚。”—甘德拉万尼亚的日记（翻译版）",
                            ["hint"] = "",
                        },
                        [10622] = 
                        {
                            ["name"] = "乌马里尔的辐光瓜尔",
                            ["category"] = "两足动物",
                            ["furnitureId"] = 8562,
                            ["icon"] = "/esoui/art/icons/mount_umarilcovenantguar.dds",
                            ["id"] = 10622,
                            ["description"] = "“沼泽人让无羽者很是恼火。‘他们游击作战。不过他们很害怕被称为瓜尔的东西。我们就利用这一点吧。’但获取所需瓜尔的时间比训练它们的时间还要长。愿它们能永远追捕乌马里尔的敌人。”——格兰德兰亚的日记（翻译版）",
                            ["hint"] = "",
                        },
                        [10623] = 
                        {
                            ["name"] = "乌马里尔的辐光森切",
                            ["category"] = "猫科动物",
                            ["furnitureId"] = 8563,
                            ["icon"] = "/esoui/art/icons/mount_umarilscovenantsenche.dds",
                            ["id"] = 10623,
                            ["description"] = "“沙漠中的游牧民与无羽者的敌人暗中交易。‘让我们驾驭着迅捷而安静的坐骑击溃他们。’和我共事的那些沙漠猫很快就适应了环境。愿它们永远为了他而潜行出击。”—甘德拉万尼亚的日记（翻译版）",
                            ["hint"] = "",
                        },
                        [10624] = 
                        {
                            ["name"] = "乌马里尔的辐光狼",
                            ["category"] = "犬科动物",
                            ["furnitureId"] = 8564,
                            ["icon"] = "/esoui/art/icons/mount_umarilscovenantwolf.dds",
                            ["id"] = 10624,
                            ["description"] = "“乌马里尔试图指引被征服者的道路。‘这种生物必须领导进攻，不轻易挫败。’在忠诚与这些特质之间取得平衡需要很长时间，愿它们永远指引着无羽者的兽群。”—甘德拉万尼亚的日记（翻译版）",
                            ["hint"] = "",
                        },
                        [10626] = 
                        {
                            ["name"] = "南威尔德草原土拨鼠",
                            ["category"] = "异域",
                            ["furnitureId"] = 8565,
                            ["icon"] = "/esoui/art/icons/pet_goldenprairiedog.dds",
                            ["id"] = 10626,
                            ["description"] = "木精灵部落将这些草原土拨鼠引入了瓦伦伍德北部，以帮助维持森林的整体健康。有些人甚至在家里养了一些。现在你会看到它们追着人类和精灵，可爱的小鼻子不停抽动着。",
                            ["hint"] = "",
                        },
                        [10627] = 
                        {
                            ["name"] = "巢盗瓦尔德瓦克",
                            ["category"] = "两足动物",
                            ["furnitureId"] = 8566,
                            ["icon"] = "/esoui/art/icons/mount_hivethiefvvardvark.dds",
                            ["id"] = 10627,
                            ["description"] = "“看那条舌头！多亏咒术师多玛瓦斯以魔导师瓦尔肯内尔的研究为基础加以改进，才有了这些吃虫子的美人儿。我听说最初他想给它们加上羽毛，但失败了。然后就有了这匹华丽的坐骑。”—死灵之地马厩主西迪欧斯·索西亚",
                            ["hint"] = "",
                        },
                        [10628] = 
                        {
