                        [8877] = 
                        {
                            ["name"] = "铁侍灵瓜尔",
                            ["category"] = "两足动物",
                            ["furnitureId"] = 7505,
                            ["icon"] = "/esoui/art/icons/mount_ironatroguar2.dds",
                            ["id"] = 8877,
                            ["description"] = "在一次醉酒后，法师塔文·奥瑟伦召唤出了第一只已知的铁侍灵瓜尔，而它却立即杀死了他的同伴们。悲痛之余，法师寻求救赎，在余生中只骑着那只瓜尔作为他所犯之错的提醒。",
                            ["hint"] = "",
                        },
                        [8878] = 
                        {
                            ["name"] = "铁侍灵森切",
                            ["category"] = "猫科动物",
                            ["furnitureId"] = 7506,
                            ["icon"] = "/esoui/art/icons/mount_ironatrosenche.dds",
                            ["id"] = 8878,
                            ["description"] = "故事讲述了玛兰丽·第仁尼，虽然被强盗束缚着，但不知怎么就潜入了梦境，并召唤出了第一只铁侍灵森切。铁侍灵森切一出现便摧毁了玛兰丽的笼子并释放了她，这样她便能杀了抓她的人，随后骑在它的熔岩之背上逃跑了。",
                            ["hint"] = "",
                        },
                        [8879] = 
                        {
                            ["name"] = "铁侍灵狼",
                            ["category"] = "犬科动物",
                            ["furnitureId"] = 7507,
                            ["icon"] = "/esoui/art/icons/mount_ironatrowolf.dds",
                            ["id"] = 8879,
                            ["description"] = "在铁侍灵的各种不同形态中，狼是最难成的。侍灵憎恨狼对于群体的依赖，渴望找到符合它们孤独本质的外形。通常只有泰姆瑞尔的顶尖法师，才能将这些熔岩巨人变化为狼的形态。",
                            ["hint"] = "",
                        },
                        [8880] = 
                        {
                            ["name"] = "大衮陆行狮鹫",
                            ["category"] = "巨型动物",
                            ["furnitureId"] = 7508,
                            ["icon"] = "/esoui/art/icons/mount_gryphon.dds",
                            ["id"] = 8880,
                            ["description"] = "“炽热的灰烬和暗黑的羽毛，尖锐的利爪和加剧的愤怒，这些都接近于剃刀魔神；至少圣人是这么说的。然而，在混沌使这头野兽扭曲之前，第仁尼就已经精心制作了这些。它的身上沾染着死地的堕落热量，无法被祛除。”——名为齐力克的斯卡芬",
                            ["hint"] = "",
                        },
                        [10929] = 
                        {
