                        [12712] = 
                        {
                            ["name"] = "镜泽碎片野猫",
                            ["category"] = "异域",
                            ["furnitureId"] = 10153,
                            ["icon"] = "/esoui/art/icons/pet_scintillatingshardsenchecub.dds",
                            ["id"] = 12712,
                            ["description"] = "这只野猫身上的碎片如今还是钝的，可以安全触摸。但它的獠牙和爪子却如针刺般锋利。随着它的体型越来越大，这些碎片将变成刀刃般锋利的琉璃，成为令人恐惧的防御武器。",
                            ["hint"] = "",
                        },
                        [12693] = 
                        {
                            ["name"] = "雪爪森切薮猫幼崽",
                            ["category"] = "异域",
                            ["furnitureId"] = 10143,
                            ["icon"] = "/esoui/art/icons/pet_snowclawsencheservalkitten.dds",
                            ["id"] = 12693,
                            ["description"] = "养了这种聪明小猫的主人可得打起十二分精神，雪地环境更是要多加留意。它们轻柔的步伐加上一身洁白的皮毛，使得它们能在雪地中瞬间不见踪影。然而，大部分小猫还是更喜爱同伴的温暖，而非冰冷的巢穴。",
                            ["hint"] = "",
                        },
                        [12692] = 
                        {
                            ["name"] = "混沌魔球组",
                            ["category"] = "魔族",
                            ["furnitureId"] = 10142,
                            ["icon"] = "/esoui/art/icons/pet_chaosballcohort.dds",
                            ["id"] = 12692,
                            ["description"] = "“或许有人会说：带着一颗自动跟屁球来比赛是在耍赖。可你又没让它跟着你！这东西安全得很，正式比赛大概也能带上去。不过场上有两颗球，估计会乱套吧。”——带球者克莱林那",
                            ["hint"] = "",
                        },
                        [12691] = 
                        {
                            ["name"] = "西威尔德寻回犬",
                            ["category"] = "驯养",
                            ["furnitureId"] = 10140,
                            ["icon"] = "/esoui/art/icons/pet_malabaltorretriever.dds",
                            ["id"] = 12691,
                            ["description"] = "“他就跟军团獒犬一样，又聪明又忠诚！而且比獒犬还要加倍亲人！但他就是有个小癖好：如果球滚到了树丛底下、水坑里，或者其他不容易看见的地方，他就懒得捡了。但这也没啥大不了的。”——军团士兵奥黛妮亚",
                            ["hint"] = "",
                        },
                        [12690] = 
                        {
                            ["name"] = "高岩红狐猴",
                            ["category"] = "异域",
                            ["furnitureId"] = 10139,
                            ["icon"] = "/esoui/art/icons/pet_highrockringtail.dds",
                            ["id"] = 12690,
                            ["description"] = "“有人认为这些狐猴有特异功能，但这纯属无稽之谈。它们只是很有‘说服力’——瞧瞧它们的大眼睛！为了让它们别再盯着你看，你肯定什么都愿意去干！”——途歇城的伊莎贝尔·奥尼斯",
                            ["hint"] = "",
                        },
                        [12684] = 
                        {
                            ["name"] = "龙尾山熊崽",
                            ["category"] = "异域",
                            ["furnitureId"] = 10137,
                            ["icon"] = "/esoui/art/icons/pet_dragontailmountainbearcub.dds",
                            ["id"] = 12684,
                            ["description"] = "要想稳妥驯服一头龙尾山熊，你最好是从小就开始养它，并用蜂蜜、浆果之类的零食作为诱惑。这种熊对甜食情有独钟，为了过上嘴瘾，它们什么都愿意做。",
                            ["hint"] = "",
                        },
                        [11552] = 
                        {
                            ["name"] = "公会召唤的幽魂",
                            ["category"] = "飞行",
                            ["furnitureId"] = 9351,
                            ["icon"] = "/esoui/art/icons/pet_guildconjuredwisp.dds",
                            ["id"] = 11552,
                            ["description"] = "“看，它或许没有太多个性，但它以自己的方式散发迷人气息。我觉得它很高兴见到你。法师公会的学徒们都很为这次召唤而自豪。你至少应该表现出钦佩的样子。”——法师公会学徒赫兰廷",
                            ["hint"] = "",
                        },
                        [12683] = 
                        {
                            ["name"] = "龙尾山熊",
                            ["category"] = "熊科动物",
                            ["furnitureId"] = 10136,
                            ["icon"] = "/esoui/art/icons/mount_dragontailmountainbear.dds",
                            ["id"] = 12683,
                            ["description"] = "“别在意我这位一脸甜蜜的老伙计。它只是闻闻你身上有没有好吃的。不用怕，它可是头严格的素食主义熊！不过它爬进蜂巢里的时候倒是吞过几只蜜蜂。”——贝尼亚·熊友",
                            ["hint"] = "",
                        },
                        [12668] = 
                        {
                            ["name"] = "镜泽龙蛙",
                            ["category"] = "异域",
                            ["furnitureId"] = 10128,
                            ["icon"] = "/esoui/art/icons/pet_mirrormoordragonfrog.dds",
                            ["id"] = 12668,
                            ["description"] = "虽然这些龙蛙外形惊人，但若论智力，就乏善可陈。当两只龙蛙面对面相遇时，它们常常会被自己映在对方身上的倒影所迷，因而陷入对峙，而且这一僵局能持续数小时之久。",
                            ["hint"] = "",
                        },
                        [9507] = 
                        {
                            ["name"] = "白霜幼麋鹿",
                            ["category"] = "异域",
                            ["furnitureId"] = 7857,
                            ["icon"] = "/esoui/art/icons/pet_platinumfawn.dds",
                            ["id"] = 9507,
                            ["description"] = "“有人说，这些麋鹿起源于死灵仪式，与躁动不安的灵魂有关。我说也许是吧。不管怎样，这些小鹿作为同伴会让人愉快，虽然它们有时会一连几个小时盯着某处发呆。”——爱林希尔的普拉斯图斯",
                            ["hint"] = "",
                        },
                        [12667] = 
                        {
                            ["name"] = "彩翼蝙蝠",
                            ["category"] = "飞行",
                            ["furnitureId"] = 10127,
                            ["icon"] = "/esoui/art/icons/pet_stainedwingbat.dds",
                            ["id"] = 12667,
                            ["description"] = "这些蝙蝠的翅膀迷人至极。虽然白天时难以发现，但当泰姆瑞尔的月光倾泄而下，这些翅膀就仿若在空中燃烧了起来。这种幻象会吸引来昆虫，为彩翼蝙蝠带来一场欢乐的盛宴。",
                            ["hint"] = "",
                        },
                        [12666] = 
                        {
                            ["name"] = "瓦沙巴花瓣蛾",
                            ["category"] = "飞行",
                            ["furnitureId"] = 10126,
                            ["icon"] = "/esoui/art/icons/pet_sylvansunbeammoth.dds",
                            ["id"] = 12666,
                            ["description"] = "“我认为耶弗尔的全部造物都蕴含了深刻的教诲，尤其是飞蛾。它们很容易为人所忽视，但它们却提醒着我们，要如何保持柔软的身段，如何轻盈地穿行于世界之中，以及如何追随光明。\"——瓦沙巴的冈德林",
                            ["hint"] = "",
                        },
                        [9510] = 
                        {
                            ["name"] = "白霜麋鹿坐骑",
                            ["category"] = "鹿科动物",
                            ["furnitureId"] = 7858,
                            ["icon"] = "/esoui/art/icons/mount_platinumelk.dds",
                            ["id"] = 9510,
                            ["description"] = "在一场仪式中，当时月光倾泻，落于雪花之上晶莹闪烁，一头白麋鹿在被注入一只从杰汉纳附近的寒冷海洋中捕获的鬼魂的智慧——至少高岩的传说是这样的。不管是真是假，这头坐骑比大多数人想象的要懂得更多。",
                            ["hint"] = "",
                        },
                        [9511] = 
                        {
                            ["name"] = "格洛丽亚雕像",
                            ["category"] = "普通",
                            ["furnitureId"] = 7859,
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_playerstatue001.dds",
                            ["id"] = 9511,
                            ["description"] = "授予2020年泰姆瑞尔团结抽奖比赛的胜者。",
                            ["hint"] = "",
                        },
                        [7464] = 
                        {
                            ["name"] = "明月蛾",
                            ["category"] = "飞行",
                            ["furnitureId"] = 6630,
                            ["icon"] = "/esoui/art/icons/pet_brightmoonslunarmoth.dds",
                            ["id"] = 7464,
                            ["description"] = "“当一只明月蛾跟随你时，乔恩与乔德的祝福也随之而来。”——月之祭司泰达扎",
                            ["hint"] = "",
                        },
                        [9513] = 
                        {
                            ["name"] = "星辰降生守卫熊",
                            ["category"] = "熊科动物",
                            ["furnitureId"] = 7861,
                            ["icon"] = "/esoui/art/icons/mount_apexcelestialbear.dds",
                            ["id"] = 9513,
                            ["description"] = "“不要被这只熊迷人的星星欺骗了，不要以为它是一种无害的魔法运输工具。回想一下星座的摇摆，并理解这个生物体现了这种力量。”——喘鸣的威伦",
                            ["hint"] = "",
                        },
                        [9514] = 
                        {
                            ["name"] = "星辰降生守卫瓜尔",
                            ["category"] = "两足动物",
                            ["furnitureId"] = 7862,
                            ["icon"] = "/esoui/art/icons/mount_celestialguar.dds",
                            ["id"] = 9514,
                            ["description"] = "据弗尔斯特罗姆的传说，一个星光熠熠的瓜尔在一个雪夜把弗拉吉国王的私生子带到了他们的村庄。没有人听到或看到这对来者的到来，直到孩子被冷哭了。瓜尔也在黎明前消失了。",
                            ["hint"] = "",
                        },
                        [7467] = 
                        {
                            ["name"] = "猩红夫诸",
                            ["category"] = "鹿科动物",
                            ["furnitureId"] = 6631,
                            ["icon"] = "/esoui/art/icons/mount_crimsonindrik.dds",
                            ["id"] = 7467,
                            ["description"] = "当夕阳的光辉洒落到被魔力浸染的鸟类羽毛上时，这只有着灵动步态的猩红夫诸就诞生了。学者们观察到，这只夫诸的魔法属性可以促进自我反思。",
                            ["hint"] = "通过将新生夫诸坐骑与四种不同的猩红浆果结合而成。结合后的新生夫诸会变为猩红夫诸。",
                        },
                        [7468] = 
                        {
                            ["name"] = "苔心夫诸",
                            ["category"] = "鹿科动物",
                            ["furnitureId"] = 6632,
                            ["icon"] = "/esoui/art/icons/mount_mossheartindrik.dds",
                            ["id"] = 7468,
                            ["description"] = "夏暮岛的学者们声称，这种夫诸是在森林中最古老的树下形成的，它们具有一种深远永恒的气息。骑着这种魔法生物的人们会发现，就算遇到再大的困境也可以迎刃而解。",
                            ["hint"] = "通过将新生夫诸坐骑与四种不同的苔心浆果结合而成。结合后的新生夫诸会变为苔心夫诸。",
                        },
                        [9517] = 
                        {
                            ["name"] = "画：乐雅文在等待",
                            ["category"] = "普通",
                            ["furnitureId"] = 7618,
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingblackwoodkeyartpainting001.dds",
                            ["id"] = 9517,
                            ["description"] = "一副乐雅文的画，它是位于尼本河河口的尼本尼城市，该城以致敬泽尼萨尔的伟大教堂出名。",
                            ["hint"] = "",
                        },
                        [12665] = 
                        {
                            ["name"] = "真理与法则石魂",
                            ["category"] = "飞行",
                            ["furnitureId"] = 10125,
                            ["icon"] = "/esoui/art/icons/pet_julianosstonewisp.dds",
                            ["id"] = 12665,
                            ["description"] = "尤里安诺斯的忠诚法师创造了这些独特的生物，以此作为表达自己虔诚信仰的艺术形式。这种幽魂象征着秩序美学、平衡感和专注能量。同时，它还能在冥想时发出美妙的专注音调。",
                            ["hint"] = "",
                        },
                        [12664] = 
                        {
                            ["name"] = "珍珠白赛普蝰蛇",
                            ["category"] = "异域",
                            ["furnitureId"] = 10124,
                            ["icon"] = "/esoui/art/icons/pet_pearlysepadder.dds",
                            ["id"] = 12664,
                            ["description"] = "白色赛普蝰蛇在野外极为罕见，因为它们独特的体色无法提供自然的伪装。它们通常只出现在圈养环境里。人们饲养它们就是为了欣赏它们鳞片的光泽和独具特色的美感。",
                            ["hint"] = "",
                        },
                        [12657] = 
                        {
                            ["name"] = "镜泽碎片森切",
                            ["category"] = "猫科动物",
                            ["furnitureId"] = 10117,
                            ["icon"] = "/esoui/art/icons/mount_scintillatingshardsenche.dds",
                            ["id"] = 12657,
                            ["description"] = "这只寒光闪闪的森切身披护甲，这不仅是为了防护自身，更是为骑手提供必要的屏障，以免骑手被覆盖其全身的刀锋般的碎片所伤。耐心的骑手会慢慢地了解到这头猛兽的安全触碰区。",
                            ["hint"] = "",
                        },
                        [12479] = 
