                        [5553] = 
                        {
                            ["name"] = "蜥蜴狼骑",
                            ["category"] = "犬科动物",
                            ["furnitureId"] = 5424,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_wolf.dds",
                            ["id"] = 5553,
                            ["description"] = "“沼泽里几乎每一位马厩主都有各种各样精良的有鳞蜥蜴坐骑可供购买，一切都是干皮人熟悉的，但专门适用于深沼泽骑行。我们的蜥蜴坐骑是如此方便，如此有鳞又风度翩翩！”——乌卡斯帕",
                            ["hint"] = "",
                        },
                        [5554] = 
                        {
                            ["name"] = "蜥蜴森切",
                            ["category"] = "猫科动物",
                            ["furnitureId"] = 5425,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_senche.dds",
                            ["id"] = 5554,
                            ["description"] = "“不止一次有人问我， ‘乌卡斯帕，为什么你的蜥蜴坐骑长得这么像泰姆瑞尔其他地方的坐骑？为什么你如此帅气的蜥蜴坐骑长得一点儿都不像蜥蜴？ ’这些个问题问得好啊！”——利尔莫斯的乌卡斯帕",
                            ["hint"] = "",
                        },
                        [5555] = 
                        {
                            ["name"] = "蜥蜴瓜尔骑",
                            ["category"] = "两足动物",
                            ["furnitureId"] = 5426,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_guar.dds",
                            ["id"] = 5555,
                            ["description"] = "“有些干皮人问， ‘既然瓜尔已经算是一种沼泽爬行类坐骑了，为什么还要杂交出像瓜尔一样的蜥蜴坐骑呢？那不会有点多此一举吗？ ’这些干皮人的洞察力异常敏锐！”——利尔莫斯的乌卡斯帕",
                            ["hint"] = "",
                        },
                        [5556] = 
                        {
                            ["name"] = "蜥蜴骆驼骑",
                            ["category"] = "骆驼科动物",
                            ["furnitureId"] = 5427,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_camel.dds",
                            ["id"] = 5556,
                            ["description"] = "“也许创造出蜥蜴骆驼骑就是为了能让我们这样英勇的亚龙人冒险家可以在类似安奎那这样气候干旱的地方旅行，或者是为了让英勇的虎人冒险家可以在黑沼泽有坐骑可用。我不知道，我就是想要拥有一头。”——希姆·贾斯",
                            ["hint"] = "",
                        },
                        [5557] = 
                        {
                            ["name"] = "蜥蜴熊骑",
                            ["category"] = "熊科动物",
                            ["furnitureId"] = 5428,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_bear.dds",
                            ["id"] = 5557,
                            ["description"] = "“所以，它是一头熊。只不过也是一只蜥蜴。而且你还能骑它？肖尔的骨头啊！我需要知道的就是这些。我要了！”——知名诺德使节桀骜者里古特",
                            ["hint"] = "",
                        },
                        [5558] = 
                        {
                            ["name"] = "蜥蜴马",
                            ["category"] = "马属动物",
                            ["furnitureId"] = 5429,
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_horse.dds",
                            ["id"] = 5558,
                            ["description"] = "“有时候亚龙人想花很长时间进行长途旅行，这时候人们会怎么办？骑上坐骑！如此一来，实用的蜥蜴就变成了形态各异的蜥蜴马，然后亚龙人就可以骑着它们，人高马大，威风凛凛！”——利尔莫斯的乌卡斯帕",
                            ["hint"] = "",
                        },
