                        [1473] = 
                        {
                            ["name"] = "蝎子混合体",
                            ["category"] = "异域",
                            ["furnitureId"] = 4483,
                            ["icon"] = "/esoui/art/icons/pet_164.dds",
                            ["id"] = 1473,
                            ["description"] = "“既然我们的化境可以被改造，能生产泰姆瑞尔境内几乎所有生物为模型的混合体，为什么不同大小的蝎子混合体如此受欢迎？它们是我们需求量最大的产品！”机械使徒如是说道。",
                            ["hint"] = "",
                        },
                        [1474] = 
                        {
                            ["name"] = "光泽尼克斯牛虫混合体坐骑",
                            ["category"] = "节肢动物",
                            ["furnitureId"] = 4754,
                            ["icon"] = "/esoui/art/icons/mounticon_lustrousnixoxfabricant.dds",
                            ["id"] = 1474,
                            ["description"] = "在圣徒洛提斯和奥尔姆斯不得不被关在庇护圣所之前，他们曾经在圣日骑着这些奇怪的混合体坐骑穿过黄铜堡垒。但这些游行早已不复存在，而这些混合体坐骑也被用于其他用途了。",
                            ["hint"] = "",
                        },
                        [11882] = 
                        {
                            ["name"] = "影暮矮脚瓜尔鸡",
                            ["category"] = "异域",
                            ["furnitureId"] = 9565,
                            ["icon"] = "/esoui/art/icons/pet_twilightbantamguar.dds",
                            ["id"] = 11882,
                            ["description"] = "这只瓜尔矮脚鸡的配色很具有伪装性。这种特色是福也是祸，因为只要稍不留神，它就会游荡走失。鉴于它轻信的态度、几乎没有天然的防御力，以及缺乏天生的生存本能……还是不要让它无人看管吧。",
                            ["hint"] = "",
                        },
                        [10717] = 
                        {
                            ["name"] = "奥罗兰多彩狼",
                            ["category"] = "犬科动物",
                            ["furnitureId"] = 8602,
                            ["icon"] = "/esoui/art/icons/mount_auroranpolychromaticwolf.dds",
                            ["id"] = 10717,
                            ["description"] = "“这条奥罗兰狼的色彩组合让我想起了缤纷殿。这种美让我痛苦，像匕首一样刺穿我的心。如果你看得太过专注，就会迷失在它永恒的光辉之中。所以不要太过入神地注视它。”—学者亚杜尔",
                            ["hint"] = "",
                        },
                        [10847] = 
                        {
                            ["name"] = "王之守卫公羊",
                            ["category"] = "鹿科动物",
                            ["furnitureId"] = 8613,
                            ["icon"] = "/esoui/art/icons/mount_cathbedraudram.dds",
                            ["id"] = 10847,
                            ["description"] = "看到这种出色的坐骑进入院子的马夫们都称被赐予了好运。照顾这些格伦姆布拉公羊不仅能带来利润，而且据说它们的出现预示着即将到来平静祥和的夜晚。",
                            ["hint"] = "",
                        },
                        [10848] = 
                        {
                            ["name"] = "桑加德剑齿虎",
                            ["category"] = "异域",
                            ["furnitureId"] = 8614,
                            ["icon"] = "/esoui/art/icons/pet_sungardsabrecat.dds",
                            ["id"] = 10848,
                            ["description"] = "桑加德之战发生后不久，这些剑齿虎就开始在这片区域游荡了。当时的学者认为是战争破坏了它们正常的栖息地。驯兽人看到了机会，找到它们的幼崽并开始当宠物饲养。",
                            ["hint"] = "",
                        },
                        [10849] = 
                        {
                            ["name"] = "梅内维亚斑点狗",
                            ["category"] = "驯养",
                            ["furnitureId"] = 8615,
                            ["icon"] = "/esoui/art/icons/pet_meneviacoachdog.dds",
                            ["id"] = 10849,
                            ["description"] = "在风暴港经常会见到这些敏锐的狗跟在手推车和马车旁小跑，它们可以威慑强盗和其他道路上的敌人。近年来，它们在泰姆瑞尔的其他地方变得流行起来，包括黑木和裂谷。",
                            ["hint"] = "",
                        },
                        [11877] = 
                        {
                            ["name"] = "蹉扎巴，矮人分解器",
                            ["category"] = "助手",
                            ["furnitureId"] = 9560,
                            ["icon"] = "/esoui/art/icons/assistant_tzozabrar_dwarvendeconstructor.dds",
                            ["id"] = 11877,
                            ["description"] = "蹉扎巴会吸入你不需要的物品，排出很可能是从矮人造物中找来的有用材料。音场干扰意味着它无法在西罗帝尔或战场使用。\r\n\r\n召唤后，你和你的队友都可以使用其提供的服务。",
                            ["hint"] = "",
                        },
                        [10853] = 
                        {
                            ["name"] = "飞升教主雕像",
                            ["category"] = "普通",
                            ["furnitureId"] = 8622,
                            ["icon"] = "/esoui/art/icons/housing_str_exc_statueascendantlord001.dds",
                            ["id"] = 10853,
                            ["description"] = "虽然仍不知道是哪位艺术家雕刻了这尊雕像，但那些亲眼见过飞升教主的人都说，它完美地展现了这位领袖的力量与仪态。这尊雕像是从飞升教团的宝藏中找到的。",
                            ["hint"] = "",
                        },
                        [9674] = 
                        {
                            ["name"] = "灭魂骏马",
                            ["category"] = "马属动物",
                            ["furnitureId"] = 7920,
                            ["icon"] = "/esoui/art/icons/mount_soulrazersteed.dds",
                            ["id"] = 9674,
                            ["description"] = "“我以为我的救赎就在眼前，我以为有人来到这个深渊找我。但我错了，这不正常——马鞍下面没有马。一个形体，没有灵魂。死亡本身会更加仁慈。”——威格纳克·恩希牢房里被撕下的纸张",
                            ["hint"] = "",
                        },
