                        [11693] = 
                        {
                            ["name"] = "蜜酒舞者蜜蜂",
                            ["category"] = "飞行",
                            ["furnitureId"] = 9525,
                            ["icon"] = "/esoui/art/icons/pet_whiterunhoneybee.dds",
                            ["id"] = 11693,
                            ["description"] = "“蜜蜂其实头脑很简单。它们尊重权力，所以它们会追随一位蜂后。只要你拿出掌权者的气势，它们就会为你工作。要是你流露出任何软弱、犹豫？那你就等着被蜇吧。”——海伊·蜜手",
                            ["hint"] = "",
                        },
                        [11692] = 
                        {
                            ["name"] = "冬堡栗色小马",
                            ["category"] = "驯养",
                            ["furnitureId"] = 9524,
                            ["icon"] = "/esoui/art/icons/mount_winterholdchestnutpony.dds",
                            ["id"] = 11692,
                            ["description"] = "在冬堡，每个孩子都会在某个时刻想要一匹这样的小马，而极少数幸运儿才会得到一匹。它们小巧的体型非常适合年轻的骑手，甚至年长的成人也将它们视为欢乐而又坚韧的宠物。",
                            ["hint"] = "",
                        },
                        [11691] = 
                        {
                            ["name"] = "伙伴狂欢魂泊典魔",
                            ["category"] = "魔族",
                            ["furnitureId"] = 9523,
                            ["icon"] = "/esoui/art/icons/pet_companionstomeshell.dds",
                            ["id"] = 11691,
                            ["description"] = "“听着，我知道魂泊典魔也需要一个栖身之地，但那可是档案塔里最珍贵的书籍之一！现在看着确实很靓丽，但等这家伙决定换个地方时，天晓得那本书会变成什么样子。”——暗语者卡尔达芬",
                            ["hint"] = "",
                        },
                        [11657] = 
                        {
                            ["name"] = "米斯特拉尔雷光虫",
                            ["category"] = "异域",
                            ["furnitureId"] = 9494,
                            ["icon"] = "/esoui/art/icons/pet_mistralthunderbug.dds",
                            ["id"] = 11657,
                            ["description"] = "谁要是拥有了这个震颤人心的小家伙，就必须学会应对不时发生的电击事故。雷光虫很擅长表现，然而它们的主要沟通方式是火花和剧烈的震动。",
                            ["hint"] = "",
                        },
                        [11656] = 
                        {
                            ["name"] = "炎龙骆驼蜥",
                            ["category"] = "骆驼科动物",
                            ["furnitureId"] = 9493,
                            ["icon"] = "/esoui/art/icons/mount_pyrodraconiccamellizard.dds",
                            ["id"] = 11656,
                            ["description"] = "“它当然不是真正的龙。这无关紧要。浓烈的着色、喷吐着硫磺，还融合了木精灵和泰尔瓦尼的魔法技艺？告诉奥瑟瑞，契约已经履行，而且超乎预期。”——魔导师瓦尔肯内尔",
                            ["hint"] = "",
                        },
                        [11652] = 
                        {
                            ["name"] = "荆棘壁虎",
                            ["category"] = "异域",
                            ["furnitureId"] = 9474,
                            ["icon"] = "/esoui/art/icons/pet_thorngecko.dds",
                            ["id"] = 11652,
                            ["description"] = "“老尖刺当然不是最可爱的宠物，但他向来十分忠诚。我偶尔会扔给他一些蛆虫，然后他就跟着我到处走。我觉得他想要的是陪伴，而不仅仅是零食。”——捕兽者马西恩",
                            ["hint"] = "",
                        },
                        [5600] = 
                        {
                            ["name"] = "空心南瓜浮游者",
