                        [11121] = 
                        {
                            ["name"] = "半岛寄居蟹",
                            ["category"] = "异域",
                            ["furnitureId"] = 8821,
                            ["icon"] = "/esoui/art/icons/pet_telvannihermitcrab.dds",
                            ["id"] = 11121,
                            ["description"] = "寄居蟹的适应能力极强。来自泰尔瓦尼半岛的寄居蟹以中空的蘑菇伞为家，并在暗精灵的花园中充当装饰品。",
                            ["hint"] = "",
                        },
                        [11120] = 
                        {
                            ["name"] = "敏感的德雷曼肯幼崽",
                            ["category"] = "魔族",
                            ["furnitureId"] = 8820,
                            ["icon"] = "/esoui/art/icons/pet_discorddremnaken.dds",
                            ["id"] = 11120,
                            ["description"] = "德雷曼肯幼崽不喜欢攻击性的行为。令人遗憾的是，抓挠下巴和拍头也在此之列。事实上，最好连最温和的眼神接触都应避免。",
                            ["hint"] = "",
                        },
                        [11072] = 
                        {
                            ["name"] = "博雅剑骑士矮人蜘蛛",
                            ["category"] = "构造体",
                            ["furnitureId"] = 8704,
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerdwarvenspider.dds",
                            ["id"] = 11072,
                            ["description"] = "“剧烈的震颤破坏了矮人制造的蜘蛛。‘它闻起来恶臭无比。让我们来帮维威克领主把它的运行机制修好。它的永久存在势必会在我们中间引发必要的改变。’于是，它与熊一起加入了队伍。”——剑骑士萨里斯的日记",
                            ["hint"] = "",
                        },
                        [11071] = 
                        {
                            ["name"] = "博雅剑骑士公羊",
                            ["category"] = "鹿科动物",
                            ["furnitureId"] = 8703,
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerram.dds",
                            ["id"] = 11071,
                            ["description"] = "“这只好奇的有角野兽闻了闻食物，之后转身离去。‘啊，好奇心驱使它行动，但谨慎使其冷静克制。对于维威克领主的研究来说，这是一种聪明的野兽。也许它能让愚人开智增慧，令智者焕发希望。’这就是它的结局。”——剑骑士萨里斯的日记",
                            ["hint"] = "",
                        },
                        [9784] = 
                        {
                            ["name"] = "花斑森切薮猫",
                            ["category"] = "猫科动物",
                            ["furnitureId"] = 7952,
                            ["icon"] = "/esoui/art/icons/mount_tyrigelsenche.dds",
                            ["id"] = 9784,
                            ["description"] = "“在哨兵城以外的任何地方旅行时，请骑上这些花斑动物。它们比我养过的所有森切薮猫都更喜爱炎热。这让我相信：几十年前，夏暮岛的流浪汉在附近的土匪洞穴里把它们抚养长大的故事。”——马夫伯尔汉",
                            ["hint"] = "",
                        },
                        [9785] = 
                        {
                            ["name"] = "夜峰高地鸵鸟",
                            ["category"] = "异域",
                            ["furnitureId"] = 7953,
                            ["icon"] = "/esoui/art/icons/pet_nightcrestfellrunn.dds",
                            ["id"] = 9785,
                            ["description"] = "亚龙人的农民把高地鸵鸟的羽毛成袋卖给猎人。即使是一只苍白的高地鸵鸟臂章，也能让猎人偷偷穿过暗木的沼泽而不被发现。",
                            ["hint"] = "",
                        },
                        [7738] = 
                        {
                            ["name"] = "谷小鹿",
                            ["category"] = "异域",
                            ["furnitureId"] = 6724,
                            ["icon"] = "/esoui/art/icons/pet_valefawn.dds",
                            ["id"] = 7738,
                            ["description"] = "虽然这只可爱的小鹿的颜色与它的亲属不同，但首先映入人们眼帘的是这只小鹿珍珠般的白色。只要给予它足够的照顾，你就能帮助它克服害羞，让它在你身边嬉戏。",
                            ["hint"] = "",
                        },
                        [7739] = 
                        {
                            ["name"] = "夜玫瑰谷小鹿",
                            ["category"] = "异域",
                            ["furnitureId"] = 6725,
                            ["icon"] = "/esoui/art/icons/pet_valefawnred.dds",
                            ["id"] = 7739,
                            ["description"] = "一位勘探者声称：“夜玫瑰的红色光芒从它诞生时便有了。如果天空是红色的，小鹿也是红色的。”虽然有些人对此嗤之以鼻，但所有人都同意一件事：夜玫瑰对危险有一种第六感，它会唤醒任何被选中的家庭。",
                            ["hint"] = "",
                        },
                        [7740] = 
                        {
                            ["name"] = "安伯辛谷小鹿",
                            ["category"] = "异域",
                            ["furnitureId"] = 6726,
                            ["icon"] = "/esoui/art/icons/pet_valefawnyellow.dds",
                            ["id"] = 7740,
                            ["description"] = "它琥珀般的金色光芒创造了一种温暖，一位马厩主说，“它可以让你在天际的星空下度过寒冷的夜晚。”你只需要让小鹿时不时地舔一口蜂蜜，就能让它留在你身边。",
                            ["hint"] = "",
                        },
                        [7741] = 
                        {
                            ["name"] = "翡翠谷小鹿",
                            ["category"] = "异域",
                            ["furnitureId"] = 6727,
                            ["icon"] = "/esoui/art/icons/pet_valefawngreen.dds",
                            ["id"] = 7741,
                            ["description"] = "有一段时间，学者们认为只有一种谷小鹿存在。现在，人们有了更好的了解，为什么会有这种变化呢？小鹿才不在乎。但是，附着绿色闪光的小鹿品种更喜欢赛跑。要是把它认作同伴的话，它甚至可能与你赛跑呢！",
                            ["hint"] = "",
                        },
                        [7742] = 
                        {
                            ["name"] = "兰花谷小鹿",
                            ["category"] = "异域",
                            ["furnitureId"] = 6728,
                            ["icon"] = "/esoui/art/icons/pet_valefawnpurple.dds",
                            ["id"] = 7742,
                            ["description"] = "一位研究谷小鹿的学者指出，紫色的紫秋谷小鹿喜欢吃花。它的名字来源于天际一个现已消失的充满植物的洞穴。“给它一朵花，它是你一生的朋友！”你手里有花吗？",
                            ["hint"] = "",
                        },
                        [9791] = 
                        {
                            ["name"] = "苹果背蝾螈",
                            ["category"] = "异域",
                            ["furnitureId"] = 8021,
                            ["icon"] = "/esoui/art/icons/pet_magmaskinsalamander.dds",
                            ["id"] = 9791,
                            ["description"] = "途歇城的强盗想要用这些生物来骚扰镇上的贵族，但事与愿违后，他们卖掉了自己的股票。你很幸运，这些蝾螈在被出售前接受了忠诚训练。",
                            ["hint"] = "",
                        },
