                        [10290] = 
                        {
                            ["name"] = "新月狐狸",
                            ["category"] = "犬科动物",
                            ["furnitureId"] = 8304,
                            ["icon"] = "/esoui/art/icons/mount_newmoonfox.dds",
                            ["id"] = 10290,
                            ["description"] = "“不要低估新月邪教所训练出的狐狸。它们闪着光的猩红双眼足以警告你离开。如果你蠢到想要偷走一只成年狐狸，那就跟奈恩说再见吧。”——太阳行者乔纳特",
                            ["hint"] = "",
                        },
                        [10277] = 
                        {
                            ["name"] = "柠檬点气母",
                            ["category"] = "飞行",
                            ["furnitureId"] = 8300,
                            ["icon"] = "/esoui/art/icons/pet_lemondotnetch.dds",
                            ["id"] = 10277,
                            ["description"] = "“颜色看起来更明亮？音乐的气味各不相同？迪尔达斯有个性化动作？你可能正在体验罕见的柠檬点气母的通感毒液。放轻松，这是无害的。只是全新的视角，永远不会害死任何人的。”——炼金术士阿利农",
                            ["hint"] = "",
                        },
                        [10244] = 
                        {
                            ["name"] = "斑点四目兽",
                            ["category"] = "巨型动物",
                            ["furnitureId"] = 8286,
                            ["icon"] = "/esoui/art/icons/mount_speckledwelwa.dds",
                            ["id"] = 10244,
                            ["description"] = "这种野蛮的四目兽引起了晶智学院的学员们的兴趣，他们甚至带了几只到席尔瓦沃德研究。为了让公众更喜爱它们，一位有事业心的保育员给它们套上鞍具，把它们“借到”野外去。",
                            ["hint"] = "",
                        },
                        [10243] = 
                        {
                            ["name"] = "锚生小马",
                            ["category"] = "异域",
                            ["furnitureId"] = 8285,
                            ["icon"] = "/esoui/art/icons/pet_planemeldpony.dds",
                            ["id"] = 10243,
                            ["description"] = "“现在，我对朋友说，看看这些暗锚碎片，没人用，没人有。我看着他的小马，这个病态的小东西，我得说，为什么不给咱们自己弄点好东西呢？”——“革新者”德兰",
                            ["hint"] = "",
                        },
                        [10242] = 
                        {
                            ["name"] = "风暴潮嚎狼",
                            ["category"] = "犬科动物",
                            ["furnitureId"] = 8280,
                            ["icon"] = "/esoui/art/icons/mount_stormsurgehowler.dds",
                            ["id"] = 10242,
                            ["description"] = "身上覆盖着珊瑚和藤壶，这种不寻常的海洋生物像湍急的水流一样移动，为它的骑手创造出平稳的旅行体验。有人推测，凯恩用海上风暴制作了它们，并把它们送到陆地上去寻找那些崇敬她的人。",
                            ["hint"] = "通过达成“至高欺凌者”成就获得。",
                        },
                        [10240] = 
                        {
                            ["name"] = "锈皮剑齿虎",
                            ["category"] = "异域",
                            ["furnitureId"] = 8277,
                            ["icon"] = "/esoui/art/icons/pet_rustpeltsabrecat.dds",
                            ["id"] = 10240,
                            ["description"] = "“我从哪儿弄来的猫？卡片。可怜的小家伙被一些走私宠物的混蛋拿来当货币使用。我在教她怎么数卡片，给我拿点酒来。”——私掠者马克",
                            ["hint"] = "",
                        },
                        [10239] = 
                        {
                            ["name"] = "深紫红寄居蟹",
                            ["category"] = "异域",
                            ["furnitureId"] = 8276,
                            ["icon"] = "/esoui/art/icons/pet_damsonhermitcrab.dds",
                            ["id"] = 10239,
                            ["description"] = "在德鲁伊教之前，在富商之前，甚至在贵族住宅之前，寄居蟹便统治着整个西斯忒斯。无论它走到哪里，都会拖着自己的东西，用那圆溜溜的眼睛看着你，好像在说：“我和你，我们没什么不同。”",
                            ["hint"] = "通过达成“失落深渊探险家”成就获得。",
                        },
                        [10238] = 
                        {
                            ["name"] = "莫萨尔城熊犬",
                            ["category"] = "驯养",
                            ["furnitureId"] = 8275,
                            ["icon"] = "/esoui/art/icons/pet_spottedbeardog.dds",
                            ["id"] = 10238,
                            ["description"] = "莫萨尔城里獒犬的威望令这座城市居民的熊犬执照变得有点……傻。不管是照看孩子还是面对入侵者，总有人要挨揍。",
                            ["hint"] = "",
                        },
                        [10237] = 
                        {
                            ["name"] = "女战士之狼",
                            ["category"] = "犬科动物",
                            ["furnitureId"] = 8274,
                            ["icon"] = "/esoui/art/icons/mount_handmaidensstormwolf.dds",
                            ["id"] = 10237,
                            ["description"] = "虽然诺德人声称这头披着闪电的狼在寻找值得服侍的凯恩勇士，但石刻之识德鲁伊并不这么认为。只有自然界的不平衡才会导致这样一种生物的结合。它的目的？找到一个能恢复平衡的骑手罢了。",
                            ["hint"] = "",
                        },
                        [7110] = 
                        {
                            ["name"] = "余烬地精犬",
                            ["category"] = "异域",
                            ["furnitureId"] = 6541,
                            ["icon"] = "/esoui/art/icons/pet_durzogemberthroat.dds",
                            ["id"] = 7110,
                            ["description"] = "因其邪恶的智慧而被培育出来的余烬地精犬，可能会智胜抚养它们长大的气母无赖哥布林。只有那些头脑更灵活的人才能让它们保持忠诚，而那个人可能就是你！",
                            ["hint"] = "",
                        },
                        [7272] = 
                        {
